// Draw spiral with cool tones
function drawSpiral(x, y, r, angle, depth) {
    if (depth > 0) {
        // Draw spiral segment
        ctx.fillStyle = ACCENT;
        ctx.beginPath();
        ctx.moveTo(x, y);
        const newX = x + Math.cos(angle) * r;
        const newY = y + Math.sin(angle) * r;
        ctx.lineTo(newX, newY);
        ctx.strokeStyle = HIGHLIGHT;
        ctx.lineWidth = 2;
        ctx.stroke();

        // Recursive call for next segment
        const nextR = r * 1.1;
        const nextAngle = angle + 0.03;
        drawSpiral(newX, newY, nextR, nextAngle, depth - 1);
    }
}

